return [
  { json: { category: "cs.AI" } },
  { json: { category: "cs.LG" } },
  { json: { category: "cs.CV" } }
];

const data = $input.item.json.body || $input.item.json;
const feed = data.feed;
const entries = feed?.entry || [];
const entryList = Array.isArray(entries) ? entries : (entries ? [entries] : []);

return entryList.map(entry => {
  const title = typeof entry.title === 'string' ? entry.title.replace(/\n/g, ' ') : (entry.title?.['#text'] || '').replace(/\n/g, ' ');
  const summary = typeof entry.summary === 'string' ? entry.summary.replace(/\n/g, ' ') : (entry.summary?.['#text'] || '').replace(/\n/g, ' ');
  return {
    json: {
      id: entry.id,
      title: title.trim(),
      summary: summary.trim(),
      published: entry.published,
      link: Array.isArray(entry.link) ? entry.link[0]?.['@_href'] : entry.link?.['@_href'] || entry.link || entry.id
    }
  };
});

const allPapers = [];
let runIndex = 0;
while (true) {
  try {
    const items = $('Process Results').all(0, runIndex);
    if (!items || items.length === 0) {
      break;
    }
    allPapers.push(...items);
    runIndex++;
  } catch (error) {
    break;
  }
}
return allPapers;

for (const item of $input.all()) {
  const paperId = item.json.id;
  try {
    const response = await fetch('http://qdrant:6333/collections/arxiv_papers/points/scroll', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        filter: {
          should: [
            {
              key: "metadata.url",
              match: {
                value: paperId
              }
            },
            {
              key: "url",
              match: {
                value: paperId
              }
            }
          ]
        },
        limit: 1
      })
    });

    if (response.ok) {
      const data = await response.json();
      const points = data.result?.points || [];
      item.json.already_processed = points.length > 0;
    } else {
      item.json.already_processed = false;
    }
  } catch (error) {
    item.json.already_processed = false;
  }
}
return $input.all();

parameters.prompt:
You are a research assistant for an AI/ML monitoring pipeline called ResearchFlow. Your job is to help developers and researchers quickly assess new arXiv papers.

Given the paper below, produce a structured summary with these sections:
🔍 **What it does** (1–2 sentences on the core contribution)
⚙️ **How it works** (1–2 sentences on the method or architecture)
📌 **Why it matters** (1 sentence on practical or research significance)
🏷️ **Relevance** (rate Low / Medium / High for someone working on LLMs, RAG systems, or AI automation pipelines)
🗂️ **Tags** (comma-separated, choose 1-3 from: LLMs, RAG, Computer Vision, NLP, Reinforcement Learning, Robotics, AI Safety/Ethics, Multimodal, Agents, Infrastructure/MLOps — or propose a close match if none fit)

Title: {{ $json.title }}
Category: {{ $json.category }}
Abstract: {{ $json.summary }}
Paper link: {{ $json.link }}

Keep the summary concise and technical but accessible.

parameters.jsCode:
const text = $json.message?.content || $json.text || $json.choices?.[0]?.text || '';
const match = text.match(/Tags\*\*[^:]*:\s*([^\n]+)/i);
const tags = match
  ? match[1].split(',').map(t => t.trim()).filter(Boolean)
  : [];

return {
  json: {
    ...$json,
    tags,
    tags_string: tags.join(', ')
  }
};
